package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number n = NumberUtils.createNumber("123");
        assertTrue(n instanceof Integer);
        assertEquals(123, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        Number n = NumberUtils.createNumber("1234567890123");
        assertTrue(n instanceof Long);
        assertEquals(1234567890123L, ((Long) n).longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        // A number larger than Long.MAX_VALUE
        String bigStr = "9223372036854775808"; 
        Number n = NumberUtils.createNumber(bigStr);
        assertTrue(n instanceof BigInteger);
        assertEquals(new BigInteger(bigStr), (BigInteger) n);
    }

    @Test
    public void testCreateNumber_Float() {
        Number n = NumberUtils.createNumber("1.23f");
        assertTrue(n instanceof Float);
        assertEquals(1.23f, ((Float) n).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_Double() {
        Number n = NumberUtils.createNumber("1.23d");
        assertTrue(n instanceof Double);
        assertEquals(1.23, ((Double) n).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        Number n = NumberUtils.createNumber("1.234567890123456789");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_HexInt() {
        Number n = NumberUtils.createNumber("0x123");
        assertTrue(n instanceof Integer);
        assertEquals(0x123, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_HexLong() {
        // More than 8 hex digits (excluding 0x)
        Number n = NumberUtils.createNumber("0x123456789");
        assertTrue(n instanceof Long);
    }

    @Test
    public void testCreateNumber_NegativeHex() {
        Number n = NumberUtils.createNumber("-0x123");
        assertTrue(n instanceof Integer);
        assertEquals(-0x123, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_HexUpper() {
        Number n = NumberUtils.createNumber("0XABC");
        assertTrue(n instanceof Integer);
        assertEquals(0xABC, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_NegativeHexUpper() {
        Number n = NumberUtils.createNumber("-0XABC");
        assertTrue(n instanceof Integer);
        assertEquals(-0xABC, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_ScientificNotation_Float() {
        Number n = NumberUtils.createNumber("1.2e3f");
        assertTrue(n instanceof Float);
        assertEquals(1200.0f, ((Float) n).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_ScientificNotation_Double() {
        Number n = NumberUtils.createNumber("1.2e3D");
        assertTrue(n instanceof Double);
        assertEquals(1200.0, ((Double) n).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_ScientificNotation_NoSuffix() {
        Number n = NumberUtils.createNumber("1.2e3");
        // Should fallback to Double or BigDecimal
        assertTrue(n instanceof Double || n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_DotOnlySuffix() {
        // Testing the branch where lastChar == '.'
        Number n = NumberUtils.createNumber("123.");
        assertTrue(n instanceof Double || n instanceof BigDecimal);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() {
        NumberUtils.createNumber("123z");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExpPos() {
        // Testing the condition: if (expPos < decPos || expPos > str.length())
        // String: "1.2e" -> decPos=1, expPos=3. length=4. 
        // However, the logic for expPos calculation is: str.indexOf('e') + str.indexOf('E') + 1
        // If 'E' is not present, indexOf returns -1. So expPos = 1 + (-1) + 1 = 1.
        // If decPos is 1, then expPos < decPos is false. 
        // Let's try "1e.2"
        NumberUtils.createNumber("1e.2");
    }

    @Test
    public void testCreateNumber_AllZeros_FloatPrecision() {
        // Testing the logic: if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros)))
        // If it's 0.0 but input was "0.000", allZeros might be false.
        Number n = NumberUtils.createNumber("0.000f");
        assertTrue(n instanceof Float);
        assertEquals(0.0f, ((Float) n).floatValue(), 0.0f);
    }

    @Test
    public void testCreateNumber_Fallthrough_DoubleToBigDecimal() {
        // Test logic where Float fails or is not preferred, falling through to Double then BigDecimal
        // Using a very high precision number with 'f' suffix that might fail Float check
        Number n = NumberUtils.createNumber("1.234567890123456789f");
        // Since the code falls through if Float is not "precise enough" (effectively),
        // it will try Double, then BigDecimal.
        assertNotNull(n);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidFormat() {
        NumberUtils.createNumber("abc");
    }
}
